package com.smarttask.service;
import com.smarttask.dto.ApiDtos.*; import com.smarttask.entity.User; import com.smarttask.repository.UserRepository; import com.smarttask.security.JwtService; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AuthService { private final UserRepository users;private final PasswordEncoder encoder;private final JwtService jwt;public AuthService(UserRepository u,PasswordEncoder e,JwtService j){users=u;encoder=e;jwt=j;} @Transactional public AuthResponse register(RegisterRequest r){String email=r.email().trim().toLowerCase();if(users.findByEmail(email).isPresent())throw new IllegalArgumentException("An account with this email already exists.");return response(users.save(new User(r.name().trim(),email,encoder.encode(r.password()))));}public AuthResponse login(LoginRequest r){User u=users.findByEmail(r.email().trim().toLowerCase()).orElseThrow(()->new IllegalArgumentException("Email or password is incorrect."));if(!encoder.matches(r.password(),u.getPasswordHash()))throw new IllegalArgumentException("Email or password is incorrect.");return response(u);}private AuthResponse response(User u){return new AuthResponse(jwt.create(u),new UserView(u.getId(),u.getName(),u.getEmail()));} }
